<?php require __DIR__.'/../includes/bootstrap.php';if(!collector_marketplace_ready())redirect('collectors/index.php');$p=collector_profile_by_slug($_GET['slug']??'');if(!$p||($p['status']!=='approved'&&!can_manage_collector($p))){http_response_code(404);exit('Collector not found.');}$s=db()->prepare("SELECT * FROM collector_items WHERE collector_id=? AND status IN('active','sold','traded') ORDER BY is_featured DESC,created_at DESC");$s->execute([$p['id']]);$items=$s->fetchAll();app_header($p['shop_name']);?><section class="profile-hero collector-profile" <?php if($p['banner_path']):?>style="background-image:linear-gradient(90deg,rgba(8,8,16,.9),rgba(8,8,16,.45)),url('<?=e(base_url($p['banner_path']))?>')"<?php endif?>><?php if($p['avatar_path']):?><img class="profile-avatar" src="<?=e(base_url($p['avatar_path']))?>" alt=""><?php endif?><div><p class="eyebrow">COLLECTOR PROFILE</p><h1><?=e($p['shop_name'])?></h1><p><?=e($p['tagline'])?></p><p><?=nl2br(e($p['bio']))?></p><p><?=e($p['location'])?> <?php if($p['website']):?> · <a href="<?=e($p['website'])?>" target="_blank">Website</a><?php endif?></p></div></section><section class="collector-grid"><?php foreach($items as $i):?><article class="collector-card"><?php if($i['image_path']):?><a href="item.php?slug=<?=urlencode($i['slug'])?>"><img src="<?=e(base_url($i['image_path']))?>" alt=""></a><?php endif?><div class="collector-card-body"><p class="eyebrow"><?=e(strtoupper(collector_listing_types()[$i['listing_type']]??''))?></p><h2><a href="item.php?slug=<?=urlencode($i['slug'])?>"><?=e($i['title'])?></a></h2><p><strong><?=$i['price']!==null?'$'.number_format((float)$i['price'],2):'Open to offers'?></strong></p></div></article><?php endforeach?></section><?php app_footer();
